=[[枚]],["unwieldText"]=[[HIW消逝之感并未随指环取下消散。这固然缘于你深知它的意义，但更因为你心甘情愿。NOR]],["wuzang"]=0},["21biwudahui04"]={["bType"]=[[戒指]],["buyPrice"]=10,["dsc"]=[[仁人殉道，赤血难凉，涓滴三载雨尚悍；忠驱义感，松竹化碧，峭立千年骨犹狂。玉髓精琢，磨为扳指，色若山黛，苍翠欲滴；英物性傲，唯志纯者可得其形。]],["equipText"]=[[HIC你戴妥扳指，神色坚定，决意与世间不义抵死相争。NOR]],["id"]=[[21biwudahui04]],["melting"]=1000,["name"]=[[NAVYBLUE旷古长青NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[戒指]],["unit"]=[[枚]],["unwieldText"]=[[HIW你取下扳指，郑重收入匣中，却始终不肯低眉。NOR]],["wuzang"]=0},["21biwudahui05"]={["bType"]=[[腰坠]],["buyPrice"]=10,["dsc"]=[[鹤州奸人流毒，专诱败类修习，鱼肉良善。豪杰轩辕氏闻之不平，挚友颜绝惘生鼎力相助，力摄群恶。传曰：罪断诸邪，迹绝霜天。]],["equipText"]=[[HIC素绦系定，你拂袖端立，身怀除恶绝艺。NOR]],["id"]=[[21biwudahui05]],["melting"]=1000,["name"]=[[WHT罪霜天NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[腰坠]],["unit"]=[[块]],["unwieldText"]=[[HIW环扣拆却，你直身敛容，不忘卫道之心。NOR]],["wuzang"]=0},["21blanzhuobiwu01"]={["bType"]=[[鞋子]],["buyPrice"]=10,["dsc"]=[[脚踏万里一线云尽散，头顶百丈三尺鬼神惊。此履由天山雪莲藕丝纹饰，穿着此履，万里山河如履平地。]],["equipText"]=[[HIW$N穿上了一双$w，顿感脚下生风，似乎前路更加宽广！]],["id"]=[[21blanzhuobiwu01]],["melting"]=1000,["name"]=[[HIY藕丝步云履NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[鞋子]],["unit"]=[[双]],["unwieldText"]=[[CYN$N将$wCYN脱下，到了休息的时候了。]],["wuzang"]=0},["21blanzhuobiwu02"]={["bType"]=[[头帽]],["buyPrice"]=10,["dsc"]=[[兜鍪新缀白盔缨，十万哀兵戴孝行;瑞兽本贪龙泉气，苦恨浓时也逆吟。此盔铸精铁为兽，饰以素缨,状若貔貅吞珠;而当盔经百战,宝珠点赤，则见貔貅怒目衔恨，血口吐焰，威光凛凛，令人胆寒。]],["equipText"]=[[HIC$N将$wHIC戴在头上，拨散盔缨，心下战声渐起，攻势一触即发。]],["id"]=[[21blanzhuobiwu02]],["melting"]=1000,["name"]=[[HIW貔貅噬火盔NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[头帽]],["unit"]=[[顶]],["unwieldText"]=[[CYN$N将$wCYN取下，顿觉轻松，重担已卸，可以稍事休息了。]],["wuzang"]=0},["21blanzhuobiwu03"]={["bType"]=[[头帽]],["buyPrice"]=10,["dsc"]=[[如意千钧棒在手，扫清寰宇定苍穹，鹤立鸡群称雄意，直做人间第一流，此冠按照齐天大圣之形象订做，以珍贵的紫金装饰而成。头戴此冠，心中顿生豪侠之气。]],["equipText"]=[[HIC$N将$wHIC戴在头上，仿佛回到了那硝烟弥漫之战场。]],["id"]=[[21blanzhuobiwu03]],["melting"]=1000,["name"]=[[HIY凤翅紫金冠NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[头帽]],["unit"]=[[顶]],["unwieldText"]=[[CYN$N将$wCYN从头上摘了下来。]],["wuzang"]=0},["21blanzhuobiwu04"]={["bType"]=[[长棍]],["buyPrice"]=10,["dsc"]=[[西行八十一难路，棍荡千妖万般魔，此棍由一块天然连为一体的寒铜之精与赤石之心打造棍身，两头点缀墨金花纹，以做纪念。]],["equipText"]=[[$N抽出一根$w握在手中，你一声长啸，长棍骤然飞出，似要将前方敌人扫荡肃清。]],["id"]=[[21blanzhuobiwu04]],["melting"]=1000,["name"]=[[HIY如意金箍棒NOR]],["rendu"]=80,["salePrice"]=10,["shoucang"]=1,["type"]=[[棍]],["type2"]=1,["unit"]=[[根]],["unwieldText"]=[[$N放下手中的$w，只见你双手轻轻一甩，长棍竟然消散在天地之间，再一看已被你负于身后。]],["wanhaodu"]=100,["weight"]=32,["wuzang"]=0,["yindu"]=55},["21chujiqin"]={["bType"]=[[古琴]],["buyPrice"]=600,["damage"]=21,["dsc"]=[[以百年桐木为底材斫制而成的古琴，琴身通体幽绿，琴背处刻有铭文“青木”二字，故得此名。信手轻弹，琴音润厚古朴，令人忘俗。]],["equipText"]=[[$N取出一把$w抱在手中。]],["id"]=[[21chujiqin]],["melting"]=1000,["name"]=[[GRN青木NOR]],["rendu"]=30,["salePrice"]=10,["shoucang"]=0,["type"]=[[乐器]],["type2"]=1,["unit"]=[[把]],["unwieldText"]=[[$N放下手中的$w。]],["wanhaodu"]=100,["weight"]=27,["wuzang"]=0,["yindu"]=66},["21guoduqin"]={["bType"]=[[古琴]],["buyPrice"]=1600,["damage"]=53,["dsc"]=[[四大名琴之一“绕梁”的仿制品。其琴音也如同“绕梁”一样，余音不断，久久不息。]],["equipText"]=[[$N取出一把$w抱在手中。]],["id"]=[[21guoduqin]],["melting"]=1000,["name"]=[[PNK挽柱NOR]],["rendu"]=38,["salePrice"]=10,["shoucang"]=1,["type"]=[[乐器]],["type2"]=1,["unit"]=[[把]],["unwieldText"]=[[$N放下手中的$w。]],["wanhaodu"]=100,["weight"]=35,["wuzang"]=90,["yindu"]=84},["21guyuweapon01"]={["bType"]=[[长剑]],["buyPrice"]=10,["damage"]=161,["dsc"]=[[乃帝王之剑，用青铜所铸，长三尺，剑身镶嵌七彩宝石，传说中帝王刘邦以此剑于大泽怒斩白蛇，其剑虹破天而起，威震秦宫千里。]],["equipText"]=[[$N「唰」的一声抽出一柄$w握在手中。]],["id"]=[[21guyuweapon01]],["melting"]=1000,["name"]=[[HIW赤霄剑NOR]],["rendu"]=70,["salePrice"]=10,["shoucang"]=1,["type"]=[[剑]],["type2"]=1,["unit"]=[[把]],["unwieldText"]=[[$N将手中的$w插回剑鞘。]],["wanhaodu"]=100,["weight"]=22,["wuzang"]=231,["yindu"]=80},["21laodongweapon01"]={["bType"]=[[对剑]],["buyPrice"]=10,["damage"]=185,["dsc"]=[[此双剑乃名匠呕心沥血之作，沉湖十年以水滋养，拭去淤泥之时剑光闪耀似破空流星，剑身所刻的星辰纹路，在双剑相组时连成龙形，挥斩间犹如银龙舞。]],["equipText"]=[[HIC$N从腰间拔出$wHIC握在手中。]],["id"]=[[21laodongweapon01]],["melting"]=1000,["name"]=[[HIW东箕双剑NOR]],["rendu"]=70,["salePrice"]=10,["shoucang"]=1,["type"]=[[双持]],["type2"]=2,["unit"]=[[双]],["unwieldText"]=[[C