R]],["id"]=[[22biwudahui02]],["melting"]=1000,["name"]=[[HIW陌上人如玉NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[戒指]],["unit"]=[[枚]],["unwieldText"]=[[HIW你将陌上人如玉取下，所念之人涌上心头。NOR]],["wuzang"]=0},["22biwudahui03"]={["bType"]=[[鞋子]],["buyPrice"]=10,["dsc"]=[[青莲之出淤泥而不染，濯清涟而不妖，诗仙李太白之靴。青色随着鞋身由上而下愈来愈深，鞋面上是一朵含苞欲放的青白色莲花。若是寂静的黑夜，鞋身上镌刻的青色流星也会浮现而出。]],["equipText"]=[[HIC你将飒沓如流星穿上，青白之莲顿时怒放，心境愈发深远。NOR]],["id"]=[[22biwudahui03]],["melting"]=1000,["name"]=[[HIC飒沓如流星NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[鞋子]],["unit"]=[[双]],["unwieldText"]=[[HIW你将飒沓如流星脱下，青白之莲缓缓收敛，心境归于平淡。NOR]],["wuzang"]=0},["22biwudahui04"]={["bType"]=[[鞋子]],["buyPrice"]=10,["dsc"]=[[粉莲之出淤泥而不染，濯清涟而不妖，诗仙李太白为妻所做之靴。粉红色彩随着鞋身由上而下愈来愈深，鞋面上是一朵含苞欲放的淡粉色莲花。若是寂静的黑夜，鞋身上镌刻的黄色星月也会浮现而出。]],["equipText"]=[[HIC你将粉莲挂星月穿上，淡粉之莲顿时怒放，心境愈发深远。NOR]],["id"]=[[22biwudahui04]],["melting"]=1000,["name"]=[[PNK粉莲挂星月NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[鞋子]],["unit"]=[[双]],["unwieldText"]=[[HIW你将粉莲挂星月脱下，淡粉之莲缓缓收敛，心境归于平淡。NOR]],["wuzang"]=0},["22biwudahui05"]={["bType"]=[[上装]],["buyPrice"]=10,["dsc"]=[[江湖二十一年，外教祸乱中原，二十九派俱聚于天都峰据敌，破贼，立天都石碑，奖此物，纪念捍卫江湖之侠者，切勿忘初心。]],["equipText"]=[[HIC白衣加身，书生意气，你一身正气，向着光明前行。NOR]],["id"]=[[22biwudahui05]],["melting"]=1000,["name"]=[[WHT了然正气身NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[上装]],["unit"]=[[件]],["unwieldText"]=[[HIW褪去白衣，你缓缓望向天都石壁，昔日的刀枪之声仿佛重新响起。NOR]],["wuzang"]=0},["22biwudahui06"]={["bType"]=[[腰坠]],["buyPrice"]=10,["dsc"]=[[笑醉春风男儿事，埙篪相和与人行。惠而好我，携手同行，不惜歌者苦，但伤知音稀。焚须灼艾，愿岁并谢，与长友兮。愿为双鸿鹄，奋翅起高飞。]],["equipText"]=[[HIC轻触玉玦，一股温情于指尖传入，似有种力量持续激励着你，顿感情重姜肱，戚戚具尔。NOR]],["id"]=[[22biwudahui06]],["melting"]=1000,["name"]=[[ORA灼艾焚须玦NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[腰坠]],["unit"]=[[块]],["unwieldText"]=[[HIW取下玉玦，心中的温情并未随之散去，仰天远望，愿君安在。长情不负，岂曰无衣？与子同袍。NOR]],["wuzang"]=0},["22biwudahui07"]={["bType"]=[[戒指]],["buyPrice"]=10,["dsc"]=[[古有苍鸢，甚美而无鸣。一日见凤凰，慕其自由，决意寻侣，其翼如青天，得侣则鸣。此戒指为追求自由向往爱情者铸就。持戒者以绝世之姿，登凌绝顶之时，即可感悟真正的自由之道。]],["equipText"]=[[HIC无形无相，此戒轻轻滑入你的指尖。指引着你朝武林最高的山峰前行。NOR]],["id"]=[[22biwudahui07]],["melting"]=1000,["name"]=[[HIC青鸢逐梦环NOR]],["salePrice"]=10,["shoucang"]=1,["type"]=[[戒指]],["unit"]=[[枚]],["unwieldText"]=[[HIW你沉浸在成为武林至尊的喜悦之中，指尖玉环悄然消散。NOR]],["wuzang"]=0},["22dwnewweapon1"]={["bType"]=[[鞋子]],["buyPrice"]=10,["dsc"]=[[鞋底边雕有水纹龙舟，鞋身绣有飞龙腾云纹样，飞龙由水纹盘旋而上直冲天际，喻有吉祥飞腾之意。]],["equipText"]=[[HIW$N将$w穿上。]],["id"]=[[22dwnewweapon1]],["name"]=[[HIB地腊NOR]],["protect"]=40,["salePrice"]=10,["shoucang"]=1,["type"]=[[鞋子]],["unit"]=[[双]],["unwieldText"]=[[CYN$N将$wCYN脱了下来。]],["wuzang"]=130},["22dwnewweapon2"]={["bType"]=[[戒指]],["buyPrice"]=10,["dsc"]=[[戒身以一块完整的翠玉精制而成，上雕飞龙踏舟，逐浪而行。龙颜不怒自威，舟行水溅好似身临其境，恍惚间耳畔似有阵阵龙吟，可见雕刻之人实乃鬼斧神工。]],["equipText"]=[[HIW$N将$w戴上，恍惚间似有龙吟阵阵。]],["id"]=[[22dwnewweapon2]],["name"]=[[HIG龙纹舟戒NOR]],["protect"]=41,["salePrice"]=10,["shoucang"]=1,["type"]=[[戒指]],["unit"]=[[枚]],["unwieldText"]=[[CYN$N将$wCYN摘下，耳畔似有似无的龙啸渐行渐远。]],["wuzang"]=132},["22dwnewweapon3"]={["bType"]=[[腰坠]],["buyPrice"]=10,["dsc"]=[[由五根颜色不同的丝绳编织而成，其中坠有翠色香囊。相传五色丝绳象征着东、西、南、北、中五个方位，蕴涵着五方神力，可以驱邪除魔，祛病强身，使人健康长寿。]],["equipText"]=[[HIW$N将$w系与腰间，顿感内心舒畅，心旷神怡。]],["id"]=[[22dwnewweapon3]],["name"]=[[HIG长命缕NOR]],["protect"]=43,["salePrice"]=10,["shoucang"]=1,["type"]=[[腰坠]],["unit"]=[[块]],["unwieldText"]=[[CYN$N将$wCYN摘下，舒畅感渐渐散去。]],["wuzang"]=136},["22dwnewweapon4"]={["bType"]=[[腰带]],["buyPrice"]=10,["dsc"]=[[此带用上好的丝绸制成，带面以金丝绣有菖蒲纹样，姿态各异，活灵活现。]],["equipText"]=[[HIW$N将$w系于腰间。]],["id"]=[[22dwnewweapon4]],["name"]=[[HIY菖蒲带NOR]],["protect"]=42,["salePrice"]=10,["shoucang"]=1,["type"]=[[腰带]],["unit"]=[[条]],["unwieldText"]=[[CYN$N将$wCYN从腰间取下。]],["wuzang"]=134},["22dwnewweapon5"]={["bType"]=[[上装]],["buyPrice"]=10,["dsc"]=[[白色绸缎制成的长袍，缎面绣有祥云暗纹，领、襟、袖中别有五色线，素而不简，简而不凡。]],["equipText"]=[[HIW$N将$w穿在身上。]],["id"]=[[22dwnewweapon5]],["name"]=[[HIW五色线袍NOR]],["protect"]=41,["salePrice"]=10,["shoucang"]=1,["type"]=[[上装]],["unit"]=[[件]],["unwieldText"]=[[CYN$N将$wCYN脱下。]],["wuzang"]=132},["22qxnewweapon1"]={["bType"]=[[古琴]],["buyPrice"]=10,["damage"]=105,["dsc"]=[[此琴古朴典雅，琴头处雕刻“星河”二字，七根琴弦颜色各异，缤纷亦然。琴声清脆空灵宛如那遥远星河，洗澈灵魂。]],["equipText"]=[[$N从背后解下$w抱在手中，轻拨琴弦发出空灵音律，震撼灵魂。]],["id"]=[[22qxnewweapon1]],["melting"]=1000,["name"]=[[HIC星河NOR]],["rendu"]=46,["salePrice"]=10,["shoucang"]=1,["type"]=[[乐器]],["type2"]=1,["unit"]=[[把]],["unwieldText"]=[[$N放下了手中的$w。]],["wanhaodu"]=100,["weight"]=42,["wuzang"]=140,["yindu"]=99},["22qxnewweapon2"]={["bType"]=[[长剑]],["buyPrice"]=10,["damage"]=104,["dsc"]=[[此剑长约三尺，剑身手工折叠锻打，铁质精纯，刃纹炫丽，手工精研。云芝型剑挡，镂雕双狮戏球。葫芦型剑首，镂雕春山秋水图。软木作剑鞘，外封边且全覆铜，满雕万字图案，并阴刻杂宝纹饰。]],["equipText"]=[[HIC$N寒芒一闪$wHIC现与手中。]],["id"]=[[22qxnewweapon2]],["melting"]=1000,["name"]=[[HIC公卿剑NOR]],["rendu"]=73,["salePrice"]=10,["shoucang"]=1,["type"]=[[剑]],["type2"]=1,["unit"]=[[柄]],["unwieldText"]=[[CYN$N将手中的$wCYN归于鞘中。]],["wanhaodu"]=100,["weight"]=18,["wuzang"]=139,["yindu"]=54},["22qxnewweapon3"]={["bType"]=[[双环]],["buyPrice"]=10,["damage"]=101,["dsc"]=[[这是一对由镔铁经千万锤炼打造而出的双环，后经工艺处理使得此双环通体皎洁如月。外侧延展出的利刃寒光闪闪，锋芒逼人。内测由握柄出延伸而出祥云纹样将环圈覆盖露出利刃，双环内各镶有一枚宝石，荧光闪闪恍若明星。]],["equipText"]=[[HIC$N从腰间抽出$wHIC握在手中。]],["id"]=[[22qxnewweapon3]],["melting"]=1000,["name"]=[[HIC玉盘双星NOR]],["rendu"]=58,["salePrice"]=10,["shoucang"]=1,["type"]=[[双持]],["type2"]=1,["unit"]=[[双]],["unwieldText"]=[[CYN$N将手中的$wCYN放回腰间。]],["wanhaodu"]=100,["weight"]=18,["wuzang"]=136,["yindu"]=63},["22qxnewweapon4"]={["bType"]=[[弯刀]],["buyPrice"]=10,["damage"]=104,["dsc"]=[[据说此刀是一位匠人参照大食国将士所用仿制而出，此刀刀柄以金银所制，上镶有数颗大小不一的宝石，刃身通体乌黑，只有刀刃处银白发亮，寒光闪闪，犹如黑夜之中的一轮新月，让人脊背发凉。]],["equipText"]=[[HIC$N从腰间取出$wHIC握在手中。]],["id"]=[[22qxnewweapon4]],["melting"]=1000,["name"]=[[HIC夜上月NOR]],["rendu"]=79,["salePrice"]=10,["shoucang"]=1,["type"]=[[刀]],["type2"]=3,["unit"]=[[柄]],["unwieldText"]=[[CYN$N将手中的$wCYN归于腰间鞘中。]],["wanhaodu"]=100,["weight"]=19,["wuzang"]=139,["yindu"]=58},["22qxnewweapon5"]={["bType"]=[[长枪]],["buyPrice"]=10,["damage"]=105,["dsc"]=[[此枪全长约为九尺，刃长约六寸。通体为寒铁精锻而制，枪尾以白银包裹雕有流云纹样，枪杆精磨银白发亮，枪头则雕有七星图，与朱缨处的弧形分刃相呼应，枪刃寒芒让人望而生寒。]],["equipText"]=[[HIC$N从背后取出$wHIC握在手中。]],["id"]=[[22qxnewweapon5]],["melting"]=1000,["name"]=[[HIC星拱NOR]],["rendu"]=60,["salePrice"]=10,["shoucang"]=1,["type"]=[[棍]